begin;
create extension if not exists pgtap with schema extensions;
select plan(15);
select has_function('public','create_meeting_with_place',array['uuid','uuid','timestamp with time zone','text','text','jsonb','text'],'exact-place creation exists');
insert into auth.users(id,email) values ('d1111111-1111-1111-1111-111111111111','place-a@example.test'),('d2222222-2222-2222-2222-222222222222','place-b@example.test'),('d3333333-3333-3333-3333-333333333333','place-c@example.test');
insert into public.profiles(id,owner_id,display_name) values ('daaaaaaa-1111-1111-1111-111111111111','d1111111-1111-1111-1111-111111111111','A'),('dbbbbbbb-2222-2222-2222-222222222222','d2222222-2222-2222-2222-222222222222','B'),('dccccccc-3333-3333-3333-333333333333','d3333333-3333-3333-3333-333333333333','C');
set local role authenticated;
select set_config('request.jwt.claim.sub','d1111111-1111-1111-1111-111111111111',true);
create temp table thread as select public.open_conversation('dbbbbbbb-2222-2222-2222-222222222222') id;
create temp table place as select '{"name":"Library","address":"476 5th Ave, New York, NY 10018","latitude":40.7532,"longitude":-73.9822}'::jsonb value;
select throws_ok($$select public.create_meeting_with_place((select id from thread),gen_random_uuid(),'2099-01-01','UTC','Library','{}','')$$,'22023',null,'incomplete address rejected');
create temp table proposal as select public.create_meeting_with_place((select id from thread),'d0000000-0000-0000-0000-000000000001','2099-01-01','UTC','Library',(select value from place),'Entrance upstairs') value;
select is((select value->'revision'->'place'->>'address' from proposal),'476 5th Ave, New York, NY 10018','exact address persisted');
select is(public.create_meeting_with_place((select id from thread),'d0000000-0000-0000-0000-000000000001','2099-01-01','UTC','Library',(select value from place),'Entrance upstairs')->>'id',(select value->>'id' from proposal),'same request returns same meeting');
select throws_ok($$select public.create_meeting_with_place((select id from thread),'d0000000-0000-0000-0000-000000000001','2099-01-01','UTC','Library',(select value||'{"latitude":40.8}'::jsonb from place),'Entrance upstairs')$$,'22023',null,'changed coordinates cannot reuse request');
select set_config('request.jwt.claim.sub','d2222222-2222-2222-2222-222222222222',true);
select public.respond_to_meeting((select (value->>'id')::uuid from proposal),gen_random_uuid(),1,'confirmed');
select public.propose_meeting_change_with_place((select (value->>'id')::uuid from proposal),'d0000000-0000-0000-0000-000000000002',2,'2099-01-01','UTC','Other Library',(select value||'{"name":"Other Library","address":"1 Main St, New York, NY","latitude":40.7}'::jsonb from place),'');
select is(public.get_meeting((select (value->>'id')::uuid from proposal))->'revision'->'place'->>'address','476 5th Ave, New York, NY 10018','pending replacement preserves agreement');
select is(public.get_meeting((select (value->>'id')::uuid from proposal))->'pending_revision'->'place'->>'address','1 Main St, New York, NY','replacement carries its own address');
select public.edit_meeting_change_with_place((select (value->>'id')::uuid from proposal),'d0000000-0000-0000-0000-000000000003',3,'2099-01-01','UTC','Edited Library',(select value||'{"name":"Edited Library","address":"2 Main St, New York, NY"}'::jsonb from place),'');
select is(public.get_meeting((select (value->>'id')::uuid from proposal))->'pending_revision'->'place'->>'address','2 Main St, New York, NY','sender edits pending change');
select lives_ok($$select public.edit_meeting_change_with_place((select (value->>'id')::uuid from proposal),'d0000000-0000-0000-0000-000000000003',3,'2099-01-01','UTC','Edited Library',(select value||'{"name":"Edited Library","address":"2 Main St, New York, NY"}'::jsonb from place),'')$$,'same edit retries safely');
select set_config('request.jwt.claim.sub','d1111111-1111-1111-1111-111111111111',true);
select throws_ok($$select public.edit_meeting_change_with_place((select (value->>'id')::uuid from proposal),gen_random_uuid(),4,'2099-01-01','UTC','Library',(select value from place),'')$$,'PT409',null,'recipient cannot edit senders change');
select throws_ok($$select public.respond_to_meeting_change((select (value->>'id')::uuid from proposal),gen_random_uuid(),3,'confirmed')$$,'PT409',null,'cannot accept an edited change using the old version');
select public.respond_to_meeting_change((select (value->>'id')::uuid from proposal),gen_random_uuid(),4,'confirmed');
select is(public.get_meeting((select (value->>'id')::uuid from proposal))->'revision'->'place'->>'address','2 Main St, New York, NY','accepted address becomes agreement');
select set_config('request.jwt.claim.sub','d3333333-3333-3333-3333-333333333333',true);
select throws_ok($$select public.get_meeting((select (value->>'id')::uuid from proposal))$$,'42501',null,'outsider cannot read exact address or activity');
select throws_ok($$select public.propose_meeting_change_with_place((select (value->>'id')::uuid from proposal),gen_random_uuid(),4,'2099-02-01','UTC','Library',(select value from place),'')$$,'42501',null,'outsider cannot propose address');
reset role;
set local role anon;
select throws_ok($$select public.create_meeting_with_place(gen_random_uuid(),gen_random_uuid(),'2099-01-01','UTC','Library','{}','')$$,'42501',null,'anonymous creation denied');
select * from finish();
rollback;
